# ---------- DB helpers ----------
def get_conn():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn


def query_df(sql, params=None):
    with get_conn() as conn:
        return pd.read_sql_query(sql, conn, params=params or [])

def _excel_bytes(vehicles_x, notes_x):
    from io import BytesIO
    buf = BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as writer:
        vehicles_x.to_excel(writer, sheet_name="vehicles", index=False)
        notes_x.to_excel(writer, sheet_name="notes", index=False)
    return buf.getvalue()

def execute(sql, params=None):
    with get_conn() as conn:
        cur = conn.cursor()
        cur.execute(sql, params or [])
        conn.commit()
        return cur.lastrowid

def ensure_log():
    execute(
        """
        CREATE TABLE IF NOT EXISTS note_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            note_id INTEGER,
            vehicle_id INTEGER,
            stock_number TEXT,
            action TEXT,
            note_type TEXT,
            old_content TEXT,
            new_content TEXT,
            original_author TEXT,
            changed_by TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
        """
    )

def log_change(note_id, vehicle_id, stock, action, note_type, old_content, new_content, original_author, changed_by):
    ensure_log()
    execute(
        """INSERT INTO note_log
           (note_id, vehicle_id, stock_number, action, note_type, old_content, new_content, original_author, changed_by)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        [note_id, vehicle_id, stock, action, note_type, old_content, new_content, original_author, changed_by or "Unknown"],
    )

ensure_log()

