# Admin gate. Password is stored as a hash, not plain text.
ADMIN_USER = "LPURDY"
ADMIN_PASS_HASH = "78310a8445a90f7d948101a76b1fd86d14f5f1b30215f5b87e5986796eeb01ca"

def admin_ok(username, password):
    if username.strip() != ADMIN_USER:
        return False
    digest = hashlib.sha256(password.encode()).hexdigest()
    return hmac.compare_digest(digest, ADMIN_PASS_HASH)

